impl Solution {
    pub fn decompress_rl_elist(nums: Vec<i32>) -> Vec<i32> {
        let mut result = Vec::new();
        for i in 0..nums.len() / 2 {
            let freq = nums[2 * i] as i32;
            let val = nums[2 * i + 1];
            for _ in 0..freq {
                result.push(val);
            }
        }
        result
    }
}

